function decodeBase64Utf8(value: string): string {
  const binary = window.atob(value);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
}

export default function Hsk5LearningComponent() {
  const html = useMemo(() => decodeBase64Utf8(HTML_BASE64), []);

  return (
    <iframe
      title="HSK5 tổng hợp từ bài 1 đến bài 9"
      srcDoc={html}
      lang="vi"
      allow="autoplay"
      style={{
        display: "block",
        width: "100%",
        height: "100dvh",
        minHeight: "100vh",
        margin: 0,
        padding: 0,
        border: 0,
        background: "#ffffff",
      }}
    />
  );
}
